import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { Effect } from 'effect';
import { runBiologyApp } from '../index.js';

runBiologyApp(42, ({ random, geometry, batch, dna, rna, pdb, ribosome, tours }) => {
  if (/[?&]embed\b/.test(location.search)) document.documentElement.classList.add('embed');
  const UP = geometry.UP;
// coarse-grained structures from the Protein Data Bank (rcsb.org): bead positions in 0.1 Å, centred, base64 Int16
const PROTEINS = {"nucleosome":{"pdb":"1KX5","n":2452,"chains":10,"xyz":"","kind":"","bases":".A.T.C.A.A.T.A.T.C.C.A.C.C.T.G.C.A.G.A.T.A.C.T.A.C.C.A.A.A.A.G.T.G.T.A.T.T.T.G.G.A.A.A.C.T.G.C.T.C.C.A.T.C.A.A.A.A.G.G.C.A.T.G.T.T.C.A.G.C.T.G.G.A.A.T.C.C.A.G.C.T.G.A.A.C.A.T.G.C.C.T.T.T.T.G.A.T.G.G.A.G.C.A.G.T.T.T.C.C.A.A.A.T.A.C.A.C.T.T.T.T.G.G.T.A.G.T.A.T.C.T.G.C.A.G.G.T.G.G.A.T.A.T.T.G.A.T.A.T.C.A.A.T.A.T.C.C.A.C.C.T.G.C.A.G.A.T.A.C.T.A.C.C.A.A.A.A.G.T.G.T.A.T.T.T.G.G.A.A.A.C.T.G.C.T.C.C.A.T.C.A.A.A.A.G.G.C.A.T.G.T.T.C.A.G.C.T.G.G.A.T.T.C.C.A.G.C.T.G.A.A.C.A.T.G.C.C.T.T.T.T.G.A.T.G.G.A.G.C.A.G.T.T.T.C.C.A.A.A.T.A.C.A.C.T.T.T.T.G.G.T.A.G.T.A.T.C.T.G.C.A.G.G.T.G.G.A.T.A.T.T.G.A.T........................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................................"},"polII":{"pdb":"1I50","n":6902,"chains":10,"xyz":"","kind":"","bases":""},"pcna":{"pdb":"1AXC","n":1461,"chains":3,"xyz":"","kind":"","bases":""},"ubiquitin":{"pdb":"1UBQ","n":146,"chains":1,"xyz":"","kind":"AAEAAQABAAEAAQABAAEAAQABAAABAAEAAQABAAEAAQABAAEAAQABAAEAAQABAAEAAQABAAEAAQABAAEAAQABAAEAAQAAAQABAAEAAQABAAEAAQABAAEAAQABAAABAAEAAQABAAEAAAEAAQABAAEAAQABAAEAAQABAAEAAQABAAEAAQABAAEAAQABAAEAAQABAAA=","bases":""},"gapdh":{"pdb":"1U8F","n":2536,"chains":4,"xyz":"","kind":"","bases":""},"kinesin":{"pdb":"3KIN","n":691,"chains":2,"xyz":"","kind":"","bases":""},"actin":{"pdb":"1J6Z","n":708,"chains":1,"xyz":"","kind":"","bases":""},"tubulin":{"pdb":"1JFF","n":1613,"chains":2,"xyz":"","kind":"","bases":""},"glut1":{"pdb":"4PYP","n":853,"chains":1,"xyz":"","kind":"","bases":""},"aquaporin":{"pdb":"1J4N","n":473,"chains":1,"xyz":"","kind":"","bases":""},"nakpump":{"pdb":"3WGU","n":2561,"chains":3,"xyz":"","kind":"","bases":""},"atpsynthase":{"pdb":"1BMF","n":5696,"chains":7,"xyz":"","kind":"","bases":""},"cytc":{"pdb":"1HRC","n":196,"chains":1,"xyz":"","kind":"AAABAAEAAQABAAABAAEAAQABAAEAAQABAAEAAQABAAEAAQABAAEAAQABAAAAAQABAAEAAQAAAQABAAEAAQAAAQABAAABAAEAAQAAAQABAAEAAAEAAQABAAEAAQABAAEAAQABAAEAAAEAAQABAAEAAQABAAEAAQABAAEAAQABAAEAAQABAAEAAQABAAEAAQAAAQABAAEAAQABAAEAAAEAAQABAAEAAQABAAEAAQABAAEAAQABAAEAAQABAAEAAQABAAEAAQ==","bases":""},"catalase":{"pdb":"1DGF","n":3844,"chains":4,"xyz":"","kind":"","bases":""}};

const { V } = geometry;
const { rand } = random;
const BASE = { A: '#ff5a5a', T: '#ffd24a', G: '#3ddc84', C: '#ff9a3c', U: '#ff7ad9' }, PAIR = { A: 'T', T: 'A', G: 'C', C: 'G' };
const BACKBONE = ['#3d7bff', '#9b5cff'], MRNA = '#ffb35c';
const HISTONE = { H3: '#ff6b6b', H4: '#ffd24f', H2A: '#6bc8ff', H2B: '#b98cff' };

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setPixelRatio(Math.min(devicePixelRatio, 2)); renderer.setSize(innerWidth, innerHeight); renderer.toneMapping = THREE.ACESFilmicToneMapping;
document.body.prepend(renderer.domElement);
const scene = new THREE.Scene(); scene.background = new THREE.Color('#070a12');
const camera = new THREE.PerspectiveCamera(32, innerWidth / innerHeight, .5, 2000); camera.position.set(0, -34, 235);
const controls = new OrbitControls(camera, renderer.domElement); controls.enableDamping = true; controls.target.set(0, -36, 0);
scene.add(new THREE.HemisphereLight('#dfe8ff', '#2a1f33', 1.4)); const sun = new THREE.DirectionalLight('#fff1df', 2.2); sun.position.set(30, 50, 40); scene.add(sun);

// lit balls drawn as points (the same look as in the cell); sizes in nanometres
const ballMat = new THREE.ShaderMaterial({
  uniforms: { uScale: { value: 1 }, uLight: { value: V(.4, .6, .7).normalize() } },
  vertexShader: `attribute float size; attribute vec3 icol; uniform float uScale; varying vec3 vCol;
    void main() { vCol = icol; vec4 mv = modelViewMatrix * vec4(position, 1.); gl_PointSize = size * uScale / max(.01, -mv.z); gl_Position = projectionMatrix * mv; }`,
  fragmentShader: `uniform vec3 uLight; varying vec3 vCol;
    void main() { vec2 q = gl_PointCoord * 2. - 1.; q.y = -q.y; float r2 = dot(q, q); if (r2 > 1.) discard;
      vec3 n = vec3(q, sqrt(1. - r2)); float d = max(dot(n, uLight), 0.); vec3 h = normalize(uLight + vec3(0., 0., 1.));
      gl_FragColor = vec4(vCol * (.3 + .9 * d) + pow(max(dot(n, h), 0.), 30.) * .2 + vCol * pow(1. - n.z, 3.) * .25, 1.); }`,
});
function balls(list, parent) {
  const g = new THREE.BufferGeometry(), n = list.length, pos = new Float32Array(n * 3), sz = new Float32Array(n), cl = new Float32Array(n * 3), c = new THREE.Color();
  list.forEach((b, i) => { pos.set([b.p.x, b.p.y, b.p.z], i * 3); sz[i] = b.s; c.set(b.c); cl.set([c.r, c.g, c.b], i * 3); });
  g.setAttribute('position', new THREE.BufferAttribute(pos, 3)); g.setAttribute('size', new THREE.BufferAttribute(sz, 1)); g.setAttribute('icol', new THREE.BufferAttribute(cl, 3));
  const pts = new THREE.Points(g, ballMat); pts.frustumCulled = false; parent.add(pts); return pts;
}
const line = (pts, r, col, parent) => parent.add(new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), pts.length * 3, r, 8), new THREE.MeshStandardMaterial({ color: col, roughness: .45, emissive: col, emissiveIntensity: .25 })));

const labels = [];
function label(at, html, cls = 'lab') { const d = document.createElement('div'); d.className = cls; d.innerHTML = html; document.body.append(d); labels.push({ at, d }); }

// ---- the new DNA: two strands as lines; each base pair is a rod across them, half in each base's colour,
//      with a small silver dot where the rod joins each strand
function newDNA(origin, len) {
  const g = new THREE.Group(); g.position.copy(origin); scene.add(g);
  const R = .9, rise = .34, tw = 2 * Math.PI / 10.5, groove = 140 * Math.PI / 180, n = Math.round(len / rise), s1 = [], s2 = [], rods = [], cols = [], joints = [];
  const rod = (a, b) => { const d = b.clone().sub(a); return new THREE.Matrix4().compose(a.clone().addScaledVector(d, .5), new THREE.Quaternion().setFromUnitVectors(V(0, 1, 0), d.clone().normalize()), V(.075, d.length(), .075)); };
  for (let i = 0; i <= n; i++) {
    const x = i * rise - len / 2, a = i * tw, b = a + groove, p = V(x, R * Math.cos(a), R * Math.sin(a)), q = V(x, R * Math.cos(b), R * Math.sin(b));
    s1.push(p); s2.push(q);
    const base = 'ATGC'[Math.floor(rand() * 4)], j1 = p.clone().lerp(q, .07), mid = p.clone().lerp(q, .5), j2 = p.clone().lerp(q, .93);   // joints on the inner side of each strand
    rods.push(rod(j1, mid), rod(mid, j2)); cols.push(new THREE.Color(BASE[base]), new THREE.Color(BASE[PAIR[base]]));
    joints.push(j1, j2);   // a base meets its strand here; the rod ends inside the sphere
  }
  line(s1, .13, BACKBONE[0], g); line(s2, .13, BACKBONE[1], g);
  const rm = new THREE.InstancedMesh(new THREE.CylinderGeometry(1, 1, 1, 10), new THREE.MeshStandardMaterial({ roughness: .4 }), rods.length);
  rods.forEach((m, i) => { rm.setMatrixAt(i, m); rm.setColorAt(i, cols[i]); }); g.add(rm);
  const jm = new THREE.InstancedMesh(new THREE.SphereGeometry(.15, 16, 12), new THREE.MeshStandardMaterial({ color: '#e4e8ef', metalness: .25, roughness: .3 }), joints.length);
  joints.forEach((j, i) => jm.setMatrixAt(i, new THREE.Matrix4().makeTranslation(j.x, j.y, j.z))); g.add(jm);
  return g;
}
// ---- the new RNA: one orange strand, each base a short rod on one side, joined to the strand by a silver ball.
//      Where the strand folds back on itself (a hairpin) its bases pair up, and that stretch looks like DNA
const RPAIR = { A: 'U', U: 'A', G: 'C', C: 'G' };
function newRNA(origin, len) {
  const g = new THREE.Group(); g.position.copy(origin); scene.add(g);
  const nts = [], rodsM = [], cols = [], joints = [], letter = () => 'AUGC'[Math.floor(rand() * 4)];
  const free = (from, to, n) => { for (let i = 0; i < n; i++) { const t = i / n, p = from.clone().lerp(to, t).add(V(0, .7 * Math.sin(t * 9), .6 * Math.cos(t * 7))); nts.push({ p, b: letter(), dir: V(0, -1, 0).applyAxisAngle(V(1, 0, 0), i * .5), len: .9 }); } };
  // a hairpin standing up from the strand: an A-form stem of paired bases and a small loop at the top
  const hairpin = (foot, k) => {
    const rise = .28, R = .9, tw = 2 * Math.PI / 11, at = (j, off, r = R, lift = 0) => { const a = j * tw + off; return foot.clone().add(V(r * Math.cos(a), (j + lift) * rise, r * Math.sin(a))); };
    const up = [], down = [], seq = [];
    for (let j = 0; j < k; j++) { up.push(at(j, 0)); down.push(at(j, 2.6)); seq.push(letter()); }
    up.forEach((x, j) => nts.push({ p: x, b: seq[j], dir: down[j].clone().sub(x).normalize(), len: x.distanceTo(down[j]) / 2 }));
    for (let m = 1; m <= 5; m++) { const f = m / 6, x = at(k - 1, 2.6 * f, R * 1.3, .8 + 1.8 * Math.sin(Math.PI * f)); nts.push({ p: x, b: letter(), dir: x.clone().sub(foot).setY(0).normalize(), len: .9 }); }
    for (let j = k - 1; j >= 0; j--) nts.push({ p: down[j], b: RPAIR[seq[j]], dir: up[j].clone().sub(down[j]).normalize(), len: up[j].distanceTo(down[j]) / 2 });
  };
  free(V(-len / 2, 0, 0), V(-2, 0, 0), 26); hairpin(V(-1.2, .4, 0), 8); free(V(1.2, 0, 0), V(len / 2, 0, 0), 26);
  line(nts.map(n => n.p), .13, MRNA, g);
  const rod = (a, b) => { const d = b.clone().sub(a); return new THREE.Matrix4().compose(a.clone().addScaledVector(d, .5), new THREE.Quaternion().setFromUnitVectors(V(0, 1, 0), d.clone().normalize()), V(.075, d.length(), .075)); };
  nts.forEach(n => { const j = n.p.clone().addScaledVector(n.dir, .1); rodsM.push(rod(j, n.p.clone().addScaledVector(n.dir, n.len))); cols.push(new THREE.Color(BASE[n.b])); joints.push(j); });
  const rm = new THREE.InstancedMesh(new THREE.CylinderGeometry(1, 1, 1, 10), new THREE.MeshStandardMaterial({ roughness: .4 }), rodsM.length);
  rodsM.forEach((m, i) => { rm.setMatrixAt(i, m); rm.setColorAt(i, cols[i]); }); g.add(rm);
  const jm = new THREE.InstancedMesh(new THREE.SphereGeometry(.15, 16, 12), new THREE.MeshStandardMaterial({ color: '#e4e8ef', metalness: .25, roughness: .3 }), joints.length);
  joints.forEach((j, i) => jm.setMatrixAt(i, new THREE.Matrix4().makeTranslation(j.x, j.y, j.z))); g.add(jm);
  return g;
}

// ---- proteins: beads from the coarse-grained structures, coloured by chain
const INFO = {
  nucleosome: ['Nucleosome', '1KX5', 'DNA wound around 8 histones'], polII: ['RNA polymerase II', '1I50', 'reads genes into mRNA'], pcna: ['PCNA clamp', '1AXC', 'holds DNA during copying'],
  ubiquitin: ['Ubiquitin', '1UBQ', 'tags proteins for recycling'], gapdh: ['GAPDH', '1U8F', 'a step of glycolysis'], actin: ['Actin', '1J6Z', 'one bead of a filament'],
  tubulin: ['Tubulin', '1JFF', 'building block of microtubules'], kinesin: ['Kinesin', '3KIN', 'motor heads that walk on microtubules'],
  glut1: ['GLUT1', '4PYP', 'lets glucose in'], aquaporin: ['Aquaporin', '1J4N', 'water channel (one of four)'], nakpump: ['Na⁺/K⁺ pump', '3WGU', 'spends ATP to pump ions'],
  atpsynthase: ['ATP synthase head', '1BMF', 'makes ATP'], cytc: ['Cytochrome c', '1HRC', 'carries electrons'], catalase: ['Catalase', '1DGF', 'splits hydrogen peroxide'],
};
const HUE = { nucleosome: 0, polII: .58, pcna: .9, ubiquitin: .14, gapdh: .33, actin: .05, tubulin: .52, kinesin: .78, glut1: .12, aquaporin: .55, nakpump: .95, atpsynthase: .08, cytc: .0, catalase: .45 };
const NUCLEOSOME_CHAINS = ['H3', 'H4', 'H2A', 'H2B', 'H3', 'H4', 'H2A', 'H2B'];   // chains A–H of 1KX5; I and J are the DNA
function protein(key, at) {
  const d = PROTEINS[key], raw = Uint8Array.from(atob(d.xyz), c => c.charCodeAt(0)), xyz = new Int16Array(raw.buffer), kind = Uint8Array.from(atob(d.kind), c => c.charCodeAt(0));
  const list = [], top = { y: -Infinity, x: 0 }, bot = { y: Infinity };
  for (let i = 0; i < d.n; i++) {
    const p = V(xyz[i * 3], xyz[i * 3 + 1], xyz[i * 3 + 2]).multiplyScalar(.01), k = kind[i], ch = k >> 2, part = k & 3;   // ångström/10 → nm
    let c;
    if (part >= 2) c = part === 3 ? BASE[d.bases[i]] ?? '#ddd' : BACKBONE[ch % 2];
    else if (key === 'nucleosome') c = new THREE.Color(HISTONE[NUCLEOSOME_CHAINS[ch]] ?? '#ccc').offsetHSL(0, 0, part ? .08 : -.02).getHex();
    else c = new THREE.Color().setHSL((HUE[key] + ch * .045) % 1, .55, (part ? .66 : .56) - (ch % 2) * .07).getHex();
    list.push({ p: p.add(at), s: part === 1 ? .45 : part === 3 ? .42 : .52, c });
    top.y = Math.max(top.y, p.y); bot.y = Math.min(bot.y, p.y);
  }
  balls(list, scene);
  const [name, pdb, what] = INFO[key];
  label(V(at.x, bot.y - .6, at.z), `<b>${name}</b><br><span>${what} · PDB ${pdb}</span>`);
  return list;
}

// ---- layout: one row per place in the cell, everything at the same scale (1 unit = 1 nm)
const ROWS = [
  ['The new DNA and RNA', null],
  ['Nucleus', ['nucleosome', 'polII', 'pcna']],
  ['Cytoplasm', ['gapdh', 'tubulin', 'actin', 'kinesin', 'ubiquitin']],
  ['Membrane', ['nakpump', 'glut1', 'aquaporin']],
  ['Mitochondria and peroxisome', ['atpsynthase', 'cytc', 'catalase']],
];
const W = k => { const d = PROTEINS[k], raw = Uint8Array.from(atob(d.xyz), c => c.charCodeAt(0)), xyz = new Int16Array(raw.buffer); let m = 0; for (let i = 0; i < d.n; i++) m = Math.max(m, Math.abs(xyz[i * 3])); return m * .02; };
let y = 30;
ROWS.forEach(([title, keys]) => {
  if (!keys) {
    newDNA(V(-12, y, 0), 30); newRNA(V(24, y, 0), 30);
    label(V(-12, y - 3, 0), '<b>DNA</b><br><span>two strands, joined by base pairs (A–T, G–C)</span>'); label(V(24, y - 3.2, 0), '<b>RNA</b><br><span>one strand with its bases (A, U, G, C); a hairpin where it folds back and pairs</span>');
    label(V(6, y + 4.5, 0), title, 'grp'); y -= 26; return;
  }
  const widths = keys.map(W), gap = 16, total = widths.reduce((a, b) => a + b, 0) + gap * (keys.length - 1);
  let x = -total / 2; keys.forEach((k, i) => { protein(k, V(x + widths[i] / 2, y, 0)); x += widths[i] + gap; });
  label(V(0, y + 12, 0), title, 'grp'); y -= 30;
});

function resize() {
  renderer.setSize(innerWidth, innerHeight); camera.aspect = innerWidth / innerHeight; camera.updateProjectionMatrix();
  ballMat.uniforms.uScale.value = renderer.getDrawingBufferSize(new THREE.Vector2()).y / (2 * Math.tan(camera.fov * Math.PI / 360));
}
addEventListener('resize', resize); resize();
const lv = V();
renderer.setAnimationLoop(() => {
  controls.update();
  lv.copy(sun.position).normalize().transformDirection(camera.matrixWorldInverse); ballMat.uniforms.uLight.value.copy(lv);
  renderer.render(scene, camera);
  labels.forEach(({ at, d }) => { const p = at.clone().project(camera), vis = p.z < 1 && Math.abs(p.x) < 1.1 && Math.abs(p.y) < 1.1; d.style.display = vis ? '' : 'none'; if (vis) { d.style.left = `${(p.x + 1) / 2 * innerWidth}px`; d.style.top = `${(1 - p.y) / 2 * innerHeight}px`; } });
});
window.__prev = { camera, controls, renderer, scene };
});
